# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs, offset=-1):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: gather
def gather(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: sift
def sift(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(gather(digest(intake(emit(render(raw))))))

